import "core-js/modules/es.array.push.js";
import "core-js/modules/es.iterator.constructor.js";
import "core-js/modules/es.iterator.filter.js";
/* eslint-disable */
import { API, graphqlOperation } from "aws-amplify";
import SnackBar from "@/components/SnackBar.vue";
import AddBusinessType from "@/components/Asset/Popups/AddBusinessType.vue";
import EditBusinessType from "@/components/Asset/Popups/EditBusinessType.vue";
import DeleteBusinessType from "@/components/Asset/Popups/DeleteBusinessType.vue";
import { create_list_edit_bussinesstype } from "@/graphql/mutations.js";
export default {
  components: {
    SnackBar,
    AddBusinessType,
    EditBusinessType,
    DeleteBusinessType
  },
  emits: ["backAction"],
  data() {
    return {
      headers: [{
        title: "Business Type Name",
        key: "bussinesstypes_name",
        sortable: false
      }, {
        title: "Actions",
        key: "actions",
        sortable: false
      }],
      tableData: [],
      tableLoading: false,
      componentcheck: 0,
      createBusinessType: false,
      editBusinessType: false,
      deleteBusinessType: false,
      businessTypeItem: {},
      SnackBarComponent: {},
      currentPage: 1,
      itemsPerPage: 20,
      paginatedItems: [],
      windowHeight: 0
    };
  },
  created() {
    this.fetch_business_types();
  },
  mounted() {
    this.updateWindowHeight();
    window.addEventListener("resize", this.updateWindowHeight);
  },
  beforeDestroy() {
    window.removeEventListener("resize", this.updateWindowHeight);
  },
  computed: {
    totalCount() {
      return this.tableData.length;
    },
    pageCount() {
      return Math.ceil(this.tableData.length / this.itemsPerPage);
    },
    visiblePages() {
      const totalPages = this.pageCount;
      const current = this.currentPage;
      const delta = 2;
      let start = Math.max(1, current - delta);
      let end = Math.min(totalPages, current + delta);
      if (end - start < 4) {
        if (start === 1) {
          end = Math.min(totalPages, start + 4);
        } else {
          start = Math.max(1, end - 4);
        }
      }
      const pages = [];
      for (let i = start; i <= end; i++) {
        pages.push(i);
      }
      return pages;
    },
    validTableData() {
      return this.tableData.filter(item => {
        return item && typeof item === "object";
      });
    }
  },
  watch: {
    currentPage() {
      this.updatePageItems();
    }
  },
  methods: {
    updatePageItems() {
      const start = (this.currentPage - 1) * this.itemsPerPage;
      const end = start + this.itemsPerPage;
      this.paginatedItems = this.validTableData.slice(start, end);
    },
    updateWindowHeight() {
      this.windowHeight = window.innerHeight - 320;
    },
    add_business_type() {
      this.componentcheck = 1;
      this.createBusinessType = true;
    },
    open_edit_dialog(item) {
      if (!item) {
        console.warn("Edit dialog called with undefined item");
        return;
      }
      this.componentcheck = 2;
      this.businessTypeItem = item;
      this.editBusinessType = true;
    },
    open_delete_dialog(item) {
      if (!item) {
        console.warn("Delete dialog called with undefined item");
        return;
      }
      this.componentcheck = 3;
      this.businessTypeItem = item;
      this.deleteBusinessType = true;
    },
    async fetch_business_types() {
      this.tableLoading = true;
      try {
        let result = await API.graphql(graphqlOperation(create_list_edit_bussinesstype, {
          input: {
            action_type: "LIST"
          }
        }));
        var response = JSON.parse(result.data.create_list_edit_bussinesstype);
        this.tableData = [];
        this.tableLoading = false;
        if (response.Status == "SUCCESS") {
          this.tableData = response.data || [];
          this.updatePageItems();
        } else {
          this.tableData = [];
        }
      } catch (error) {
        this.tableLoading = false;
        this.tableData = [];
        this.SnackBarComponent = {
          SnackbarVmodel: true,
          SnackbarColor: "red",
          SnackbarText: error.errors?.[0]?.message || "Error fetching business types",
          timeout: 5000,
          Top: true
        };
      }
    },
    success_info(val) {
      this.SnackBarComponent = {
        SnackbarVmodel: true,
        SnackbarColor: "green",
        SnackbarText: val,
        timeout: 5000,
        Top: true
      };
      this.createBusinessType = false;
      this.editBusinessType = false;
      this.deleteBusinessType = false;
      this.fetch_business_types();
    },
    error_info(val) {
      this.SnackBarComponent = {
        SnackbarVmodel: true,
        SnackbarColor: "red",
        SnackbarText: val,
        timeout: 5000,
        Top: true
      };
    }
  }
};
